          variant="secondary"
          endContent={<Badge variant="warning" label={12} />}
        />
        <Button
          label="Updates"
          variant="ghost"
          endContent={<Badge variant="neutral" label="New" />}
        />
      </Stack>
    </Stack>
  );
}
